let userDocs=[];

async function fetchUserDocs(){
  try {
    const url = user ? `${API_BASE}/api/user/documents?author=${encodeURIComponent(user)}` : `${API_BASE}/api/user/documents`;
    const res = await fetch(url);
    if(res.ok){
      userDocs = await res.json();
    }
  } catch(e) {
    console.warn('Backend unavailable, using local cache:', e);
  }
  list();
}

function list(){
  const row=d=>{
    const isCleared = (d.status || '').toLowerCase().includes('clear');
    const isEscalated = (d.status || '').toLowerCase().includes('board') || (d.status || '').toLowerCase().includes('escalat');
    const bg = isCleared ? 'var(--acid)' : (isEscalated ? 'var(--pink)' : 'var(--sky)');
    return `
      <div class="hist" onclick="openDocStatus(${d.id})">
        <div class="sc" style="background:${bg};font-size:14px;padding:6px 10px;min-width:110px">${d.status || 'Under Review'}</div>
        <div style="flex:1"><b>${d.title}</b><br><span class="mono">DOC-${d.id} · ${d.created_at || 'Recent'} · ${d.word_count || 0} words</span></div>
        <span class="chip">view status receipt →</span>
      </div>
    `;
  };
  const recentItems = userDocs.slice(0,3);
  $('#recent').innerHTML=recentItems.length ? `<div class="card">${recentItems.map(row).join('')}</div>` : '<div class="card"><p class="mono">No submissions yet. Drop documents above to log your drafts.</p></div>';
  $('#all').innerHTML=userDocs.length ? userDocs.map(row).join('') : '<p class="mono" style="padding:20px">No documents in your submission ledger.</p>';
}

function openDocStatus(id){
  const doc = userDocs.find(d=>d.id===id);
  if(!doc) return;
  $('#ds-id').textContent = `SUBMISSION RECEIPT · DOC-${doc.id}`;
  $('#ds-title').textContent = doc.title;
  $('#ds-meta').textContent = `Submitted: ${doc.created_at || 'Recently'} · ${doc.word_count || 0} words · Author: ${doc.author || user || 'Student'}`;

  const isCleared = (doc.status || '').toLowerCase().includes('clear');
  const isEscalated = (doc.status || '').toLowerCase().includes('board') || (doc.status || '').toLowerCase().includes('escalat');
  const badgeBg = isCleared ? 'var(--acid)' : (isEscalated ? 'var(--pink)' : 'var(--sky)');

  $('#ds-badge').style.background = badgeBg;
  $('#ds-badge').textContent = doc.status || 'Under Review';

  if(isCleared){
    $('#ds-desc').innerHTML = `<b>Status: Cleared.</b> Your document has passed institutional verification standards. Integrity criteria satisfied.`;
  } else if(isEscalated){
    $('#ds-desc').innerHTML = `<b>Status: Board Review.</b> Your document has been escalated for secondary reviewer evaluation. Please contact your department coordinator for details.`;
  } else {
    $('#ds-desc').innerHTML = `<b>Status: Under Review.</b> Your submission is logged in the queue. Human reviewers examine matching passages according to departmental guidelines.`;
  }

  go('doc-status');
}

