async function uploadMultiple(filesList){
  const files = Array.from(filesList);
  if(files.length === 0) return;

  $('#up').style.display='block';
  $('#fn').textContent = files.length > 1 ? `${files.length} documents selected (${files.map(f=>f.name).slice(0,3).join(', ')}${files.length>3?'...':''})` : files[0].name;

  let p=10;
  $('#pb').style.width=p+'%';$('#pc').textContent=p+'%';
  $('#ps').textContent=files.length > 1 ? `Uploading ${files.length} documents to institutional review repository…` : 'uploading…';

  const formData = new FormData();
  for(let i=0; i<files.length; i++){
    formData.append('files', files[i]);
  }
  formData.append('author', user || 'Student');

  const progressInterval = setInterval(()=>{
    if(p < 85){
      p += Math.round(5 + Math.random() * 8);
      $('#pb').style.width=Math.min(85, p)+'%';
      $('#pc').textContent=Math.min(85, p)+'%';
      if(p > 35 && p < 65) $('#ps').textContent='logging documents & queuing in examiner database…';
      if(p >= 65) $('#ps').textContent='generating submission tracking receipt…';
    }
  }, 200);

  try {
    const response = await fetch(`${API_BASE}/api/upload-batch`, {
      method: 'POST',
      body: formData
    });

    clearInterval(progressInterval);
    $('#pb').style.width='100%';$('#pc').textContent='100%';$('#ps').textContent='complete';

    if(response.ok){
      const data = await response.json();
      toast(`Successfully uploaded ${data.files_count} document(s)!`);
      await fetchUserDocs();
      setTimeout(()=>{
        $('#up').style.display='none';
        if(data.documents && data.documents[0]){
          openDocStatus(data.documents[0].id);
        } else if(userDocs[0]) {
          openDocStatus(userDocs[0].id);
        }
      }, 700);
    } else {
      toast('Upload failed: ' + response.statusText);
      $('#up').style.display='none';
    }
  } catch(err) {
    clearInterval(progressInterval);
    console.error('Upload error:', err);
    toast('Error connecting to backend API');
    $('#up').style.display='none';
  }
}

