async function fetchReports(){
  try {
    const res = await fetch(`${API_BASE}/api/reports`);
    if(res.ok){
      const data = await res.json();
      reps = data.map(r=>({
        id: 'SYN-' + r.id,
        raw_id: r.id,
        name: r.doc_a_title || 'Untitled Draft',
        v: Math.round(r.exact_similarity || 0),
        p: Math.round(r.semantic_similarity || 0),
        c: 4,
        total: Math.round(r.overall_similarity || 0),
        d: r.created_at ? r.created_at.slice(0, 16) : 'recently',
        explanation: r.explanation || '',
        evidence: r.evidence || []
      }));
    }
  } catch(e) {
    console.warn('Backend unavailable, using local cache:', e);
  }
  list();
}

function list(){
  const row=r=>`<div class="hist" onclick="open_('${r.id}')"><div class="sc" style="background:${r.total>20?'var(--pink)':'var(--acid)'}">${r.total}%</div><div style="flex:1"><b>${r.name}</b><br><span class="mono">${r.id} · ${r.d}</span></div><span class="chip">view →</span></div>`;
  const recentItems = reps.slice(0,3);
  $('#recent').innerHTML=recentItems.length ? `<div class="card">${recentItems.map(row).join('')}</div>` : '<div class="card"><p class="mono">No reports yet. Drop a file above to run your first scan.</p></div>';
  $('#all').innerHTML=reps.length ? reps.map(row).join('') : '<p class="mono" style="padding:20px">No reports in history.</p>';
}

async function open_(id){
  cur = reps.find(r=>r.id===id);
  if(!cur) return;
  $('#rid').textContent=cur.id;
  $('#rt').textContent=cur.name + (cur.doc_b_title ? ' vs ' + cur.doc_b_title : '');

  // Try fetching detailed report with full text and evidence
  if(cur.raw_id){
    try {
      const res = await fetch(`${API_BASE}/api/reports/${cur.raw_id}`);
      if(res.ok){
        const det = await res.json();
        cur.doc_a_text = det.doc_a_text;
        cur.doc_b_text = det.doc_b_text;
        cur.doc_b_title = det.doc_b_title;
        cur.explanation = det.explanation;
        cur.evidence = det.evidence || [];
      }
    } catch(e) {
      console.warn('Error fetching report details:', e);
    }
  }

  draw();
  go('rep');
}

function draw(){
  const xc=$('#xc').classList.contains('on'),xq=$('#xq').classList.contains('on');
  const a=cur.v,b=cur.p,c=xc||xq?0:cur.c,t=cur.total || (a+b+c);
  $('#ring').style.setProperty('--p',t);$('#rv').textContent=t+'%';
  $('#rs').textContent=t<15?'Low overall similarity. Passages appear independent and pass baseline integrity criteria.':(cur.explanation || 'Significant overlap detected for reviewer examination.');

  $('#badge-v').textContent = `Verbatim: ${a}%`;
  $('#badge-p').textContent = `Paraphrase: ${b}%`;

  // Format transparent insights & reasons
  let insightDesc = '';
  if(a > 0 && b > 0){
    insightDesc = `<b>Compound Match Profile:</b> Contains <b>${a}% exact verbatim text</b> and <b>${b}% paraphrased structure</b>. Identical sequences share continuous n-grams, while paraphrased sections exhibit semantic alignment despite synonym substitutions or active/passive syntax rewrites.`;
  } else if(a > 0){
    insightDesc = `<b>Predominantly Verbatim Match (${a}%):</b> High literal n-gram copy detected across sentences without lexical variation. Flagged for direct unattributed text duplication.`;
  } else if(b > 0){
    insightDesc = `<b>Predominantly Paraphrased Match (${b}%):</b> Sentences preserve the conceptual thesis and argument logic with altered vocabulary, syntactic rearranging, or retained domain anchors. Flagged as semantic derivation.`;
  } else {
    insightDesc = `<b>Original Work:</b> Document exhibits low textual similarity (${t}%). Passages appear independently written.`;
  }

  if(cur.explanation && cur.explanation.includes('Indicator Notice')){
    insightDesc += `<br><span style="color:#555;font-size:13px;margin-top:6px;display:block">⚖ <i>${cur.explanation}</i></span>`;
  }
  $('#insight-text').innerHTML = insightDesc;

  $('#doc-a-name').textContent = cur.name || 'Draft (Doc A)';
  $('#doc-b-name').textContent = cur.doc_b_title || 'Corpus Reference (Doc B)';

  // Build Side-by-Side documents with matched highlighted spans
  let docA_text = cur.doc_a_text || '';
  let docB_text = cur.doc_b_text || '';

  if(!docA_text && cur.evidence && cur.evidence.length > 0){
    docA_text = cur.evidence.map(e=>e.sentence_a).filter(Boolean).join('\n\n');
  }
  if(!docB_text && cur.evidence && cur.evidence.length > 0){
    docB_text = cur.evidence.map(e=>e.sentence_b).filter(Boolean).join('\n\n');
  }

  let docAHtml = docA_text || 'No document text stored.';
  let docBHtml = docB_text || 'Reference comparison text not stored.';
  let evidenceHtml = '';

  if(cur.evidence && cur.evidence.length > 0){
    cur.evidence.forEach((ev, idx)=>{
      const isExact = (ev.type === 'Exact Match' || (ev.type && ev.type.toLowerCase().includes('verbatim')));
      const tag = isExact ? 'a' : 'b';
      const badgeClass = isExact ? 'badge-v' : 'badge-p';
      const typeLabel = isExact ? '🔴 Verbatim (Exact)' : '🔵 Paraphrase (Semantic)';
      const sentA = ev.sentence_a || '';
      const sentB = ev.sentence_b || '';

      if(sentA && docAHtml.includes(sentA)){
        docAHtml = docAHtml.split(sentA).join(`<span class="hl ${tag}" data-idx="${idx}" data-s="${tag}">${sentA}</span>`);
      }
      if(sentB && docBHtml.includes(sentB)){
        docBHtml = docBHtml.split(sentB).join(`<span class="hl ${tag}" data-idx="${idx}" data-s="${tag}">${sentB}</span>`);
      }

      const scoreNum = Math.round(ev.score || 0);
      const sharedWords = ev.shared_terms && ev.shared_terms.length > 0 ? ev.shared_terms.slice(0, 6).join(', ') : '';

      evidenceHtml += `
        <div class="s ${tag}" data-idx="${idx}" data-s="${tag}" style="margin-bottom:12px">
          <div class="row" style="justify-content:space-between;margin-bottom:6px">
            <span class="${badgeClass}">${typeLabel} · ${scoreNum}% confidence</span>
            <span class="mono" style="font-size:11px">Evidence #${idx+1}</span>
          </div>
          <p style="margin:4px 0 6px"><b>Doc A:</b> &ldquo;${sentA}&rdquo;</p>
          <p style="margin:4px 0 6px;opacity:.9"><b>Doc B:</b> &ldquo;${sentB}&rdquo;</p>
          <div style="background:#fff;border:1.5px solid var(--ink);border-radius:10px;padding:8px;margin-top:8px">
            <b style="font-size:12px;font-family:var(--m);display:block;margin-bottom:2px">WHY FLAGGED:</b>
            <span style="font-size:13px">${ev.reason || 'Similarity detected between passages.'}</span>
            ${sharedWords ? `<div class="mono" style="margin-top:4px;font-size:11px;color:#444">Anchor Terms: ${sharedWords}</div>` : ''}
          </div>
        </div>
      `;
    });
  } else {
    evidenceHtml = '<p class="mono" style="padding:16px">No specific overlapping passages flagged in this report.</p>';
  }

  $('#doc-a-content').innerHTML = docAHtml;
  $('#doc-b-content').innerHTML = docBHtml;
  $('#evidence-container').innerHTML = evidenceHtml;

  // Interactivity: Clicking any evidence or highlighted passage cross-highlights
  $$('.hl, .srcs .s').forEach(el=>{
    el.onclick=()=>{
      const idx = el.dataset.idx;
      $$('.srcs .s').forEach(s=>s.classList.toggle('on', s.dataset.idx === idx));
      $$('.hl').forEach(h=>h.style.outline = h.dataset.idx === idx ? '2.5px solid var(--ink)' : 'none');
    };
  });
}

