  if(files.length === 0) return;

  $('#up').style.display='block';
  $('#fn').textContent = files.length > 1 ? `${files.length} documents selected (${files.map(f=>f.name).slice(0,3).join(', ')}${files.length>3?'...':''})` : files[0].name;

  let p=10;
