  const formData = new FormData();
  for(let i=0; i<files.length; i++){
    formData.append('files', files[i]);
  }
  formData.append('author', user || 'Student');

  const progressInterval = setInterval(()=>{
    if(p < 85){
      p += Math.round(5 + Math.random() * 8);
      $('#pb').style.width=Math.min(85, p)+'%';
      $('#pc').textContent=Math.min(85, p)+'%';
      if(p > 35 && p < 65) $('#ps').textContent=files.length > 1 ? `Extracting texts & computing ${files.length * (files.length - 1) / 2} pairwise combinations…` : 'reading passages…';
      if(p >= 65) $('#ps').textContent='evaluating with ProtocolX ML classifier…';
