}

function renderMatrix(pairs, totalDocs){
  const wrap = $('#batch-wrap');
  const matrix = $('#matrix');
  const stats = $('#batch-stats');
  wrap.style.display = 'block';
  stats.textContent = `${totalDocs} Documents · ${pairs.length} Pair Comparisons`;

  matrix.innerHTML = pairs.map(p=>{
    const isFlagged = p.status && p.status.includes('Flagged');
    const bg = isFlagged ? 'var(--pink)' : (p.overall_similarity >= 15 ? 'var(--sky)' : 'var(--acid)');
    return `
      <div class="matrix-card" onclick="open_('SYN-${p.id}')">
        <div class="row" style="justify-content:space-between;margin-bottom:8px">
          <div class="sc" style="background:${bg};font-size:18px;padding:2px 8px">${p.overall_similarity}%</div>
          <span class="chip" style="font-size:10px">${p.status}</span>
        </div>
        <b>${p.doc_a_title}</b>
        <div class="mono" style="font-size:11px;color:#555;margin:2px 0">vs ${p.doc_b_title}</div>
        <div class="row" style="gap:6px;margin-top:8px">
          <span class="badge-v" style="font-size:10px">Exact: ${Math.round(p.exact_similarity)}%</span>
          <span class="badge-p" style="font-size:10px">Para: ${Math.round(p.semantic_similarity)}%</span>
        </div>
      </div>
    `;
  }).join('');
}
